// pyformat.mjs — Python-style repr() formatting, no regex, pure ESM.
//
// reprString(s): exact equivalent of Python 3 repr() for a str.
// reprList(arr): exact equivalent of repr() for a list of str
//                (elements joined with ", ", "[]" when empty).

// Approximation of Python's str.isprintable() for a single code point.
// Python treats categories Cc, Cf, Cs, Co, Cn, Zl, Zp and Zs-other-than-space
// as non-printable. Implemented as explicit range checks (no Unicode tables
// available without dependencies); covers all assigned non-printable ranges
// relevant in practice plus noncharacters and lone surrogates.
function isPrintable(cp) {
  // C0 / C1 controls (Cc)
  if (cp < 0x20 || (cp >= 0x7f && cp <= 0x9f)) return false;
  // Lone surrogates (Cs)
  if (cp >= 0xd800 && cp <= 0xdfff) return false;
  // Soft hyphen (Cf)
  if (cp === 0xad) return false;
  // Arabic format chars (Cf)
  if (cp >= 0x600 && cp <= 0x605) return false;
  if (cp === 0x61c || cp === 0x6dd || cp === 0x70f) return false;
  // Private use (Co): BMP + planes 15/16
  if (cp >= 0xe000 && cp <= 0xf8ff) return false;
  if (cp >= 0xf0000 && cp <= 0xffffd) return false;
  if (cp >= 0x100000 && cp <= 0x10fffd) return false;
  // Noncharacters (Cn): U+FDD0..U+FDEF and U+xFFFE/U+xFFFF of every plane
  if (cp >= 0xfdd0 && cp <= 0xfdef) return false;
  if ((cp & 0xfffe) === 0xfffe && cp >= 0xfffe) return false;
  // Space separators other than plain space (Zs)
  if (cp === 0x1680 || cp === 0x202f || cp === 0x205f || cp === 0x3000) return false;
  if (cp >= 0x2000 && cp <= 0x200a) return false;
  if (cp === 0xa0) return false;
  // Line/paragraph separators (Zl, Zp)
  if (cp === 0x2028 || cp === 0x2029) return false;
  // Zero-width and bidi format chars (Cf)
  if (cp >= 0x200b && cp <= 0x200f) return false;
  if (cp >= 0x202a && cp <= 0x202e) return false;
  if (cp >= 0x2060 && cp <= 0x2064) return false;
  if (cp >= 0x2066 && cp <= 0x206f) return false;
  if (cp === 0xfeff) return false;
  // Interlinear annotation anchors (Cf)
  if (cp >= 0xfff9 && cp <= 0xfffb) return false;
  // Supplementary format chars (Cf)
  if (cp >= 0x1bca0 && cp <= 0x1bca3) return false;
  if (cp >= 0x1d173 && cp <= 0x1d17a) return false;
  if (cp === 0xe0001 || (cp >= 0xe0020 && cp <= 0xe007f)) return false;
  return true;
}

function hexEscape(cp) {
  const hex = cp.toString(16);
  if (cp <= 0xff) return '\\x' + hex.padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + hex.padStart(4, '0');
  return '\\U' + hex.padStart(8, '0');
}

export function reprString(s) {
  // Quote selection: prefer '; use " only when s contains ' but not ".
  let hasSingle = false;
  let hasDouble = false;
  for (const ch of s) {
    if (ch === "'") hasSingle = true;
    else if (ch === '"') hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (isPrintable(cp)) {
      out += ch;
    } else {
      out += hexEscape(cp);
    }
  }
  out += quote;
  return out;
}

export function reprList(arr) {
  if (arr.length === 0) return '[]';
  let out = '[';
  for (let i = 0; i < arr.length; i++) {
    if (i > 0) out += ', ';
    out += reprString(arr[i]);
  }
  out += ']';
  return out;
}

